CREATE OR REPLACE FUNCTION public.card_level_xp_award(p_source text, p_level integer, p_levels integer[], p_b jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  c jsonb := p_b->'card_level';
  x numeric := (c->>'catchup_x')::numeric;
  top numeric := (c->>'catchup_top')::numeric;
  base numeric; n int; s numeric;
begin
  if p_source is null or p_source not in ('hunt', 'dungeon') then
